insert into auth.identities (
  id, user_id, provider_id, provider, identity_data, last_sign_in_at, created_at, updated_at
)
select
  gen_random_uuid(), u.id, u.id::text, 'email',
  jsonb_build_object('sub', u.id::text, 'email', u.email, 'email_verified', true),
  now(), now(), now()
from auth.users u
where u.email like '%@demo.roompair.example'
  and not exists (
    select 1 from auth.identities i where i.user_id = u.id and i.provider = 'email'
  );

-- The sign-up trigger has already created a bare profile for each account.
update public.profiles p set
  name = d.name, age = d.age, status = d.status, occupation = d.occupation,
  university = d.university, languages = d.languages, gender = d.gender,
  city = d.city, neighborhood = d.neighborhood, bio = d.bio,
  photo_url = d.photo_url, photos = d.photos, tags = d.tags, prompts = d.prompts,
  intent = d.intent, budget_min = d.budget_min, budget_max = d.budget_max,
  move_date = d.move_date, stay_months = d.stay_months,
  cleanliness = d.cleanliness, social = d.social, sleep = d.sleep,
  smokes = d.smokes, has_pets = d.has_pets, guests = d.guests,
  home_days = d.home_days, noise = d.noise, sharing = d.sharing,
  verified = d.verified, active = d.active,
  demo_likes_newcomers = d.demo_likes_newcomers, is_demo = true, onboarded = true
from (values
  ('00000000-0000-4000-a000-000000000001'::uuid, 'Ella', 23, 'student', 'Design student', 'Art Academy of Latvia',
   array['Latvian', 'English']::text[], 'woman', 'Riga', 'Āgenskalns',
   'Design student, weekend market regular, and the person who always brings home one more plant. Looking for a calm home with good company.',
   '/images/ella-1.jpg', array['/images/ella-1.jpg', '/images/ella-2.jpg']::text[], array['Plant parent', 'Slow mornings', 'Design & art']::text[],
   '[{"question":"The best thing about living here…","answer":"A kitchen you can linger in, a little balcony for slow mornings, and plants that are mostly still alive."},{"question":"When we disagree, I usually…","answer":"Bring it up over tea the same day. Small things stay small that way."}]'::jsonb,
   'have-room', 350, 650, (date_trunc('month', current_date + 60) + interval '1 month')::date + 0, 12,
   4, 3, 'flexible', false, false,
   'sometimes', 'sometimes', 'medium', 'some',
   true, true, true),
  ('00000000-0000-4000-a000-000000000002'::uuid, 'Leo', 24, 'student', 'Architecture student', 'Riga Technical University',
   array['Italian', 'English']::text[], 'man', 'Riga', 'Centrs',
   'Usually cycling somewhere, sketching a building, or making too much pasta. I like a tidy space and a flatmate I can call a friend.',
   '/images/leo-1.jpg', array['/images/leo-1.jpg', '/images/leo-2.jpg']::text[], array['Cycling', 'Pasta nights', 'Architecture']::text[],
   '[{"question":"My ideal Sunday at home…","answer":"Coffee, a really long breakfast, and opening every window for five minutes. Then a bike ride before it gets dark."},{"question":"My share of the chores is usually…","answer":"Dishes the same evening and the bathroom every Saturday. I like a rota on the fridge."}]'::jsonb,
   'find-room', 400, 600, (date_trunc('month', current_date + 60) + interval '1 month')::date + 4, 12,
   4, 3, 'flexible', false, false,
   'sometimes', 'rarely', 'medium', 'some',
   true, true, true),
  ('00000000-0000-4000-a000-000000000003'::uuid, 'Maya', 22, 'student', 'Psychology student', 'University of Latvia',
   array['Latvian', 'English', 'Russian']::text[], 'woman', 'Riga', 'Avoti',
   'A quiet reader with a very social kitchen. I love independent films, fresh bread, and a home where everyone can just be themselves.',
   '/images/maya-1.jpg', array['/images/maya-1.jpg', '/images/maya-2.jpg']::text[], array['Book club', 'Film nights', 'Baking']::text[],
   '[{"question":"What makes me a good flatmate…","answer":"There is usually banana bread. I will respect your closed door, and I will absolutely ask about your book."},{"question":"What you should know about the people here…","answer":"It''s me and Kārlis, a quiet master''s student who plays chess online most evenings."}]'::jsonb,
   'have-room', 350, 550, (date_trunc('month', current_date + 60) + interval '1 month')::date + 0, 12,
   4, 2, 'flexible', false, false,
   'rarely', 'often', 'low', 'some',
   true, true, true),
  ('00000000-0000-4000-a000-000000000004'::uuid, 'Noah', 25, 'student', 'Software engineering student', 'Riga Technical University',
   array['English', 'German']::text[], 'man', 'Riga', 'Skanste',
   'Code by day, climbing by evening. Moving to Riga for my master’s and looking for a relaxed place with enough desk space for a second monitor.',
   '/images/noah-1.jpg', array['/images/noah-1.jpg', '/images/noah-2.jpg']::text[], array['Bouldering', 'Good coffee', 'Gaming']::text[],
   '[{"question":"A house rule I''d never break…","answer":"Say things before they turn into things. Also, the last person to make coffee starts the next pot."},{"question":"After a long day I…","answer":"Climb for an hour, cook something simple and put my headphones on."}]'::jsonb,
