   'find-room', 320, 500, (date_trunc('month', current_date + 60) + interval '1 month')::date - 4, 12,
   3, 4, 'flexible', false, false,
   'rarely', 'sometimes', 'medium', 'some',
   true, true, false),
  ('00000000-0000-4000-a000-000000000070'::uuid, 'Andrei', 29, 'working', 'Tattoo artist', 'A studio in Grīziņkalns',
   array['Russian', 'English', 'Latvian']::text[], 'nonbinary', 'Riga', 'Grīziņkalns',
   'Tattoo artist, they/them. The flat is colourful and full of plants. Vegan kitchen, friendly snake (in a tank, always).',
   '/images/andrei-1.jpg', array['/images/andrei-1.jpg', '/images/andrei-2.jpg']::text[], array['Art & design', 'Plants', 'Music']::text[],
   '[{"question":"My favourite spot in the neighbourhood…","answer":"The bench by the water where nobody else seems to go."},{"question":"My ideal Sunday at home…","answer":"Cooking something that takes three hours while a podcast plays."}]'::jsonb,
   'have-room', 280, 430, (date_trunc('month', current_date + 60) + interval '1 month')::date + 4, 12,
   4, 5, 'late', false, true,
   'often', 'sometimes', 'medium', 'some',
   false, true, false),
  ('00000000-0000-4000-a000-000000000071'::uuid, 'Mariam', 25, 'student', 'Dentistry student', 'Rīga Stradiņš University',
   array['English', 'Russian', 'German']::text[], 'woman', 'Riga', 'Pārdaugava',
   'From Tbilisi. I bring khachapuri to every gathering. Organised, warm, and a little too invested in my flatmates'' love lives.',
   '/images/mariam-1.jpg', array['/images/mariam-1.jpg', '/images/mariam-2.jpg']::text[], array['Baking', 'Film nights', 'Yoga']::text[],
   '[{"question":"When we disagree, I usually…","answer":"Say it plainly and kindly the same day, then let it go."},{"question":"My ideal Sunday at home…","answer":"A long run, a longer shower, then the sofa and a film."}]'::jsonb,
   'find-room', 300, 470, (date_trunc('month', current_date + 60) + interval '1 month')::date + 0, 18,
   3, 4, 'flexible', false, false,
   'often', 'rarely', 'medium', 'most',
   true, true, false),
  ('00000000-0000-4000-a000-000000000072'::uuid, 'Henrik', 31, 'working', 'Game developer', 'A game studio in Riga',
   array['English', 'German']::text[], 'man', 'Riga', 'Teika',
   'Norwegian, new in town for a studio job. Quiet, dry humour, big on shared dinners and small on drama. I have a cat.',
   '/images/henrik-1.jpg', array['/images/henrik-1.jpg', '/images/henrik-2.jpg']::text[], array['Gaming', 'Board games', 'Cooking']::text[],
   '[{"question":"After a long day I…","answer":"Go for a walk by the river, whatever the weather."},{"question":"A house rule I''d never break…","answer":"Shoes off at the door."}]'::jsonb,
   'find-room', 380, 560, (date_trunc('month', current_date + 60) + interval '1 month')::date + 14, 18,
   5, 4, 'early', false, true,
   'sometimes', 'often', 'low', 'some',
   false, true, false)
) as d (
  id, name, age, status, occupation, university, languages, gender, city,
  neighborhood, bio, photo_url, photos, tags, prompts, intent, budget_min,
  budget_max, move_date, stay_months, cleanliness, social, sleep, smokes,
  has_pets, guests, home_days, noise, sharing, verified, active,
  demo_likes_newcomers
)
where p.id = d.id;

