from (values
  ('00000000-0000-4000-b000-000000000001'::uuid, 'A sunny room in Āgenskalns',
   'Your own light-filled bedroom in a two-bedroom apartment. A shared kitchen, wooden floors, and a little balcony for slow mornings. €420/month including estimated utilities.',
   420, '/images/ella-room-1.jpg', array['/images/ella-room-1.jpg', '/images/ella-room-2.jpg', '/images/ella-room-3.jpg']::text[], 'Riga', 'Āgenskalns',
   true, 420, false, true, 1,
   'Tram 10 · 12 min to the centre', 'Quiet after 23:00 on weekdays. Shoes off inside.'),
  ('00000000-0000-4000-b000-000000000003'::uuid, 'A peaceful corner in Avoti',
   'A furnished room in a cosy three-bedroom flat, with a shared living room and space for your books. €380/month including estimated utilities.',
   380, '/images/maya-room-1.jpg', array['/images/maya-room-1.jpg', '/images/maya-room-2.jpg', '/images/maya-room-3.jpg']::text[], 'Riga', 'Avoti',
   true, 380, false, true, 2,
   'Bus 3 · 15 min to the University of Latvia', 'Guests are fine, just tell us first. We share the basics like oil, salt and coffee.'),
  ('00000000-0000-4000-b000-000000000005'::uuid, 'A calm, light-filled flat',
   'A private bedroom with a large desk in a quiet two-bedroom flat. Shared kitchen and courtyard access. €460/month including estimated utilities.',
   460, '/images/sofia-room-1.jpg', array['/images/sofia-room-1.jpg', '/images/sofia-room-2.jpg', '/images/sofia-room-3.jpg']::text[], 'Riga', 'Āgenskalns',
   true, 460, true, false, 1,
   'Tram 2 · 10 min to Rīga Stradiņš University', 'Quiet after 22:00. No smoking anywhere, balcony included.'),
  ('00000000-0000-4000-b000-000000000007'::uuid, 'Green views in Teika',
   'A bright private room in a friendly two-bedroom home shared with one student and one cat. €360/month including estimated utilities.',
   360, '/images/ines-room-1.jpg', array['/images/ines-room-1.jpg', '/images/ines-room-2.jpg', '/images/ines-room-3.jpg']::text[], 'Riga', 'Teika',
   true, 360, false, true, 1,
   'Tram 11 · 20 min to the centre', 'Fig stays out of your room if you like. Recycling goes out every Friday.'),
  ('00000000-0000-4000-b000-000000000011'::uuid, 'Quiet room in a Teika two-room flat',
   'A simple, bright room in a small Soviet-era flat with a green courtyard. Shared kitchen and bathroom with me.',
