   true, 380, false, true, 1,
   'Tram 11 · 15 min to the centre', 'Quiet after 22:00 on weeknights. Shoes off at the door.'),
  ('00000000-0000-4000-b000-000000000012'::uuid, 'Big room with high ceilings in the centre',
