   false, 520, false, true, 2,
   '5 min walk to the Central Market', 'Bikes in the courtyard, not the hallway. Recycling every Monday.'),
  ('00000000-0000-4000-b000-000000000013'::uuid, 'Room in an old wooden house with a garden',
   'A cosy room in a wooden house in Āgenskalns, with a shared kitchen and a small garden with an apple tree.',
   400, '/images/amira-room-1.jpg', array['/images/amira-room-1.jpg', '/images/amira-room-2.jpg', '/images/amira-room-3.jpg']::text[], 'Riga', 'Āgenskalns',
   true, 400, false, true, 1,
   'Tram 4 · 12 min to the centre', 'Garden chores shared in summer. Guests welcome, just say hi first.'),
  ('00000000-0000-4000-b000-000000000014'::uuid, 'Attic room in the Old Town',
   'A small attic room with a skylight and a sloped ceiling, in the middle of Riga Old Town.',
   560, '/images/marta-room-1.jpg', array['/images/marta-room-1.jpg', '/images/marta-room-2.jpg', '/images/marta-room-3.jpg']::text[], 'Riga', 'Vecrīga',
   true, 560, false, true, 1,
   'Walk everywhere · 10 min to RTU', 'Mind your head on the beam! Guests until midnight.'),
  ('00000000-0000-4000-b000-000000000015'::uuid, 'Bright room with a balcony in Grīziņkalns',
