   true, 390, false, true, 1,
   'Tram 2 · 10 min to the centre', 'Quiet during exam weeks. No smoking inside.'),
  ('00000000-0000-4000-b000-000000000025'::uuid, 'Minimal room in a Centrs flat',
   'A calm, uncluttered room with high ceilings in a renovated building. The living room has a record player and a long dining table.',
