   false, 360, false, true, 1,
   'Tram 6 · 20 min to the centre', 'Early nights on weekdays.'),
  ('00000000-0000-4000-b000-000000000028'::uuid, 'Quiet room for a quiet person',
   'A simple, warm room in a renovated block. I work nights, so the flat is silent most of the day and I keep it that way.',
   330, '/images/mikael-room-1.jpg', array['/images/mikael-room-1.jpg', '/images/mikael-room-2.jpg', '/images/mikael-room-3.jpg']::text[], 'Riga', 'Purvciems',
   true, 330, false, true, 1,
   'Trolleybus 18 · 20 min to the centre', 'Quiet at all hours. No parties.'),
  ('00000000-0000-4000-b000-000000000031'::uuid, 'Sunny room, well-fed flatmate',
