   470, '/images/carmen-room-1.jpg', array['/images/carmen-room-1.jpg', '/images/carmen-room-2.jpg', '/images/carmen-room-3.jpg']::text[], 'Riga', 'Centrs',
   true, 470, false, true, 1,
   '8 min walk to the Central Market', 'Clean as you cook.'),
  ('00000000-0000-4000-b000-000000000033'::uuid, 'Garden-side room in Teika',
   'A ground-floor room that opens onto a small shared garden. One cat lives here and will decide whether she likes you.',
   370, '/images/ieva-room-1.jpg', array['/images/ieva-room-1.jpg', '/images/ieva-room-2.jpg', '/images/ieva-room-3.jpg']::text[], 'Riga', 'Teika',
   false, 370, false, true, 1,
   'Tram 6 · 18 min to the centre', 'Cat stays. Water the tomatoes in August.'),
  ('00000000-0000-4000-b000-000000000036'::uuid, 'Room in a bike-filled flat',
   'A big room in an old Avoti flat with a tiled stove. Hallway full of bikes, walls full of prints, darkroom in the bathroom now and then.',
   320, '/images/tunde-room-1.jpg', array['/images/tunde-room-1.jpg', '/images/tunde-room-2.jpg', '/images/tunde-room-3.jpg']::text[], 'Riga', 'Avoti',
   false, 320, false, true, 1,
   'Trolleybus 13 · 8 min to the centre', 'Bikes live in the hallway. Be nice.'),
  ('00000000-0000-4000-b000-000000000038'::uuid, 'Room with a river view on Ķīpsala',
   'A modern room with a view of the Daugava and fast wired internet. I work from home, so weekdays are calm.',
   520, '/images/pavel-room-1.jpg', array['/images/pavel-room-1.jpg', '/images/pavel-room-2.jpg', '/images/pavel-room-3.jpg']::text[], 'Riga', 'Ķīpsala',
   true, 520, true, true, 1,
   'Bus 57 · 7 min to the old town', 'No calls in the living room during work hours.'),
  ('00000000-0000-4000-b000-000000000041'::uuid, 'Small room above the bakery street',
   'A small, sweet room in a wooden house, with a shared balcony full of flowers. It smells of bread most mornings.',
   340, '/images/freja-room-1.jpg', array['/images/freja-room-1.jpg', '/images/freja-room-2.jpg', '/images/freja-room-3.jpg']::text[], 'Riga', 'Grīziņkalns',
   true, 340, false, true, 1,
   'Tram 11 · 12 min to the centre', 'Quiet after 22:00, I get up at six.'),
  ('00000000-0000-4000-b000-000000000043'::uuid, 'Room with a meadow smell',
   'A light room in a wooden house, with dried flowers on the walls and a big shared kitchen table. Courtyard with lilacs.',
   380, '/images/agnese-room-1.jpg', array['/images/agnese-room-1.jpg', '/images/agnese-room-2.jpg', '/images/agnese-room-3.jpg']::text[], 'Riga', 'Āgenskalns',
   false, 380, false, true, 1,
   'Tram 2 · 12 min to the centre', 'No smoking. Flowers everywhere, sorry.'),
  ('00000000-0000-4000-b000-000000000045'::uuid, 'Calm room in a translator''s flat',
   'A calm room facing the courtyard in a quiet Centrs building. I''m home most of the day, working quietly. A shy cat lives here.',
   430, '/images/yuki-room-1.jpg', array['/images/yuki-room-1.jpg', '/images/yuki-room-2.jpg', '/images/yuki-room-3.jpg']::text[], 'Riga', 'Centrs',
   true, 430, false, true, 1,
   '6 min walk to the Central Station', 'Quiet in the day. The cat is shy, let her come to you.'),
  ('00000000-0000-4000-b000-000000000047'::uuid, 'Tidy room in a family building',
   'A tidy, bright room in a well-kept building with a lift. The kitchen is spotless and I''d like to keep it that way.',
   360, '/images/fatima-room-1.jpg', array['/images/fatima-room-1.jpg', '/images/fatima-room-2.jpg', '/images/fatima-room-3.jpg']::text[], 'Riga', 'Purvciems',
   true, 360, false, true, 1,
   'Trolleybus 18 · 22 min to the centre', 'No alcohol in shared rooms. Quiet after 22:00.'),
  ('00000000-0000-4000-b000-000000000048'::uuid, 'Tall room in an art nouveau flat',
   'A tall room with a stucco ceiling and a tiled stove, in a flat with about two thousand books. Dinner together a few times a week.',
   590, '/images/lars-room-1.jpg', array['/images/lars-room-1.jpg', '/images/lars-room-2.jpg', '/images/lars-room-3.jpg']::text[], 'Riga', 'Quiet Centre',
   false, 590, false, true, 1,
   '10 min walk to the old town', 'Considerate hours. Books go back on the shelf.'),
  ('00000000-0000-4000-b000-000000000051'::uuid, 'Step-free room in a new Skanste flat',
   'A bright room in a new building with a lift and no steps anywhere. Big living room, balcony, bike storage downstairs.',
   490, '/images/katrina-room-1.jpg', array['/images/katrina-room-1.jpg', '/images/katrina-room-2.jpg', '/images/katrina-room-3.jpg']::text[], 'Riga', 'Skanste',
   true, 490, true, true, 1,
   'Bus 24 · 10 min to the centre', 'Sports gear stays in the hallway cupboard.'),
  ('00000000-0000-4000-b000-000000000056'::uuid, 'Old-town room with a roof terrace',
   'A room under the roof in the old town, with beams and a shared terrace looking at the church spires. Lively street, quiet courtyard side.',
   440, '/images/mustafa-room-1.jpg', array['/images/mustafa-room-1.jpg', '/images/mustafa-room-2.jpg', '/images/mustafa-room-3.jpg']::text[], 'Riga', 'Vecrīga',
   true, 440, false, true, 1,
   'In the old town · everything on foot', 'Late hours are fine. Terrace is for everyone.'),
  ('00000000-0000-4000-b000-000000000058'::uuid, 'Simple room near the river',
   'A simple room in a block by the Daugava promenade. Big friendly dog in the flat. I smoke on the balcony only.',
   300, '/images/viktor-room-1.jpg', array['/images/viktor-room-1.jpg', '/images/viktor-room-2.jpg', '/images/viktor-room-3.jpg']::text[], 'Riga', 'Ķengarags',
   false, 300, false, true, 1,
   'Bus 3 · 25 min to the centre', 'Dog is part of the deal.'),
  ('00000000-0000-4000-b000-000000000061'::uuid, 'Bright room with a home office nook',
   'A bright room in a new building, with its own bathroom and a desk nook. I travel twice a month, so you often have the place to yourself.',
   580, '/images/adaeze-room-1.jpg', array['/images/adaeze-room-1.jpg', '/images/adaeze-room-2.jpg', '/images/adaeze-room-3.jpg']::text[], 'Riga', 'Skanste',
   true, 580, true, true, 1,
   'Bus 24 · 10 min to the centre', 'Tidy shared rooms. Guests welcome with a heads-up.'),
  ('00000000-0000-4000-b000-000000000063'::uuid, 'Room with a balcony in Avoti',
   'A lived-in room with a balcony over a courtyard, in a flat with a lot of records and one adopted cat. I keep odd hours.',
   370, '/images/sofie-room-1.jpg', array['/images/sofie-room-1.jpg', '/images/sofie-room-2.jpg', '/images/sofie-room-3.jpg']::text[], 'Riga', 'Avoti',
   false, 370, false, true, 1,
   'Trolleybus 13 · 8 min to the centre', 'Music until 22:00. The cat goes out, don''t worry.'),
